import{_ as r,a0 as s,w as p,s as u,ao as o,I as t,x as i,a1 as T,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"有哪些不錯的命令列HTTP客户端？ | LCTT x X-CMD","titleTemplate":false,"description":"有哪些不錯的命令列HTTP客户端？ | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"有哪些不錯的命令列HTTP客户端？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"有哪些不錯的命令列HTTP客户端？ | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150429 What are good command line HTTP clients","title":"有哪些不錯的命令列HTTP客户端？","tag":"201506","desc":""},"relativePath":"201506/20150429 What are good command line HTTP clients.md","filePath":"[post].md"}'),P={name:"201506/20150429 What are good command line HTTP clients.md"};function a(d,l,m,H,g,w){const n=s("Link");return p(),u("div",null,[l[26]||(l[26]=o('<h1 id="有哪些不錯的命令列http客户端" tabindex="-1">有哪些不錯的命令列HTTP客户端？ <a class="header-anchor" href="#有哪些不錯的命令列http客户端" aria-label="Permalink to “有哪些不錯的命令列HTTP客户端？”">​</a></h1><p>“整體大於它的各部分之和”，這是引自希臘哲學家和科學家的亞里士多德的名言。這句話特別切中Linux。在我看來，Linux最強大的地方之一就是它的協作性。Linux的實用性並不僅僅源自大量的開源程序（命令列）。相反，其協作性來自於這些程序的綜合利用，有時是結合成更大型的應用。</p><p>Unix哲學引發了一場“軟件工具”的運動，關注開發簡潔，基礎，乾淨，模組化和擴展性好的代碼，並可以運用於其他的項目。這種哲學成為了許多的Linux項目的一個重要的元素。</p><p>好的開源開發者寫程序為了確保該程序儘可能運行得好，並且同時能與其他程序很好地協作。目標就是使用者擁有一堆方便的工具，每一個力求幹好一件事。許多程序能獨立工作得很好。</p><p>這篇文章討論3個開源命令列HTTP客户端。這些客户端可以讓你使用命令列從互聯網上下載文件。但同時，他們也可以用於許多有意思的地方，如測試，調式和與HTTP服務器或web應用交互。對於HTTP架構師和API設計人員來説，使用命令列操作HTTP是一個值得花時間學習的技能。如果你需要經常使用API，HTTPie和cURL就非常有價值。</p><p>###HTTPie###</p><p><img src="http://www.linuxlinks.com/portal/content/reviews/Internet/Screenshot-httpie.png" alt="HTTPie in action"></p><p>HTTPie（發音 aych-tee-tee-pie）是一款開源的命令列HTTP客户端。它是一個命令列界面，便於手工操作的類cURL工具。</p><p>該軟件的目標是使得與Web服務器的交互儘可能的人性化。其提供了一個簡單的http命令，允許使用簡單且自然的語句發送任意的HTTP請求，並顯示不同顏色的輸出。HTTPie可以用於測試，調試，以及與HTTP服務器的常規交互。</p><h4 id="功能包括" tabindex="-1">功能包括：#### <a class="header-anchor" href="#功能包括" aria-label="Permalink to “功能包括：####”">​</a></h4><ul><li>生動而直觀的語法格式</li><li>經過格式化的彩色終端輸出</li><li>內建JSON支持</li><li>支持表單和文件上傳</li><li>支持HTTPS，代理和認證</li><li>任意數據請求</li><li>自定義請求頭</li><li>持久會話</li><li>類Wget的下載</li><li>支持Python 2.6，2.7和3.x</li><li>支持Linux，Mac OS X 和 Windows</li><li>支持插件</li><li>文檔</li><li>單元測試覆蓋</li></ul><hr>',12)),t("ul",null,[t("li",null,[l[1]||(l[1]=i("網站:",-1)),T(n,{href:"http://httpie.org/"},{default:e(()=>[...l[0]||(l[0]=[i("httpie.org",-1)])]),_:1})]),l[2]||(l[2]=t("li",null,"開發者: Jakub Roztočil",-1)),l[3]||(l[3]=t("li",null,"證書: 開源",-1)),l[4]||(l[4]=t("li",null,"版本號: 0.9.2",-1))]),l[27]||(l[27]=t("p",null,"###cURL###",-1)),l[28]||(l[28]=t("p",null,[t("img",{src:"http://www.linuxlinks.com/portal/content/reviews/Internet/Screenshot-cURL.png",alt:"cURL in action"})],-1)),l[29]||(l[29]=t("p",null,"cURL是一個開源的命令列工具，用於使用URL語句傳輸數據，支持DICT, FILE, FTP, FTPS, GOPHER, HTTP, HTTPS,IMAP, IMAPS, LDAP, LDAPS, POP3, POP3S, RTMP, RTSP, SCP, SFTP, SMTP, SMTPS, TELNET和TFTP等協議。",-1)),l[30]||(l[30]=t("p",null,"cURL支持SSL證書，HTTP POST，HTTP PUT，FTP上傳，基於表單的HTTP上傳，代理，緩存，用户名+密碼的認證方式(Basic, Digest, NTLM, Negotiate, kerberos...)，文件續傳，代理通道和一些其他的有用功能。",-1)),l[31]||(l[31]=t("h4",{id:"功能包括-1",tabindex:"-1"},[i("功能包括：#### "),t("a",{class:"header-anchor",href:"#功能包括-1","aria-label":"Permalink to “功能包括：####”"},"​")],-1)),l[32]||(l[32]=t("ul",null,[t("li",null,"支持配置文件"),t("li",null,"一個單獨命令列請求多個URL"),t("li",{"one,":"","two,":"",three:""},"支持匹配： [0-13]，"),t("li",null,"一個命令上傳多個文件"),t("li",null,"自定義最大傳輸速度"),t("li",null,"重定向了標準錯誤輸出"),t("li",null,"支持Metalink")],-1)),l[33]||(l[33]=t("hr",null,null,-1)),t("ul",null,[t("li",null,[l[6]||(l[6]=i("網站: ",-1)),T(n,{href:"http://curl.haxx.se/"},{default:e(()=>[...l[5]||(l[5]=[i("curl.haxx.se",-1)])]),_:1})]),l[7]||(l[7]=t("li",null,"開發者: Daniel Stenberg",-1)),l[8]||(l[8]=t("li",null,"證書: MIT/X derivate license",-1)),l[9]||(l[9]=t("li",null,"版本號: 7.42.0",-1))]),l[34]||(l[34]=o('<p>###Wget###</p><p><img src="http://www.linuxlinks.com/portal/content/reviews/Utilities/Screenshot-Wget.png" alt="Wget in action"></p><p>Wget是一個從網絡服務器獲取信息的開源軟件。其名字源於World Wide Web 和 get。Wget支持HTTP，HTTPS和FTP協議，同時也可以通過HTTP代理獲取信息。</p><p>Wget可以根據HTML頁面的鏈接，創建遠程網絡站點的本地副本，完全重造源站點的目錄結構。這種方式被稱作“遞歸下載”。</p><p>Wget設計上增強了低速或者不穩定的網絡連接。</p><p>功能包括：</p><ul><li>使用REST和RANGE恢復中斷的下載</li><li>使用文件名通配符，支持遞歸地對目錄鏡像</li><li>基於NLS的消息文件支持多語言</li><li>可選的轉換下載文檔裏地絕對鏈接為相對鏈接，使得下載文檔可以在本地相互鏈接</li><li>可以在大多數類UNIX操作系統和微軟Windows上運行</li><li>支持HTTP代理</li><li>支持HTTP cookie</li><li>支持HTTP持久連接</li><li>無人照管/後台操作</li><li>當對遠程鏡像時，使用本地文件時間戳來決定是否需要重新下載文檔</li></ul><hr>',8)),t("ul",null,[t("li",null,[l[11]||(l[11]=i("站點: ",-1)),T(n,{href:"https://www.gnu.org/software/wget/"},{default:e(()=>[...l[10]||(l[10]=[i("www.gnu.org/software/wget/",-1)])]),_:1})]),l[12]||(l[12]=t("li",null,"開發者: Hrvoje Niksic, Gordon Matzigkeit, Junio Hamano, Dan Harkless, and many others",-1)),l[13]||(l[13]=t("li",null,"證書: GNU GPL v3",-1)),l[14]||(l[14]=t("li",null,"版本號: 1.16.3",-1))]),l[35]||(l[35]=t("hr",null,null,-1)),t("p",null,[l[16]||(l[16]=i("via: ",-1)),T(n,{href:"http://www.linuxlinks.com/article/20150425174537249/HTTPclients.html"},{default:e(()=>[...l[15]||(l[15]=[i("http://www.linuxlinks.com/article/20150425174537249/HTTPclients.html",-1)])]),_:1})]),t("p",null,[l[19]||(l[19]=i("作者：Frazer Kline 譯者：",-1)),T(n,{href:"https://github.com/wi-cuckoo"},{default:e(()=>[...l[17]||(l[17]=[i("wi-cuckoo",-1)])]),_:1}),l[20]||(l[20]=i(" 校對：",-1)),T(n,{href:"https://github.com/wxy"},{default:e(()=>[...l[18]||(l[18]=[i("wxy",-1)])]),_:1})]),t("p",null,[l[23]||(l[23]=i("本文由 ",-1)),T(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...l[21]||(l[21]=[i("LCTT",-1)])]),_:1}),l[24]||(l[24]=i(" 原創翻譯，",-1)),T(n,{href:"http://linux.cn/"},{default:e(()=>[...l[22]||(l[22]=[i("Linux中國",-1)])]),_:1}),l[25]||(l[25]=i(" 榮譽推出",-1))])])}const f=r(P,[["render",a]]);export{S as __pageData,f as default};
